    class TestFailure final : public std::runtime_error
    {
    public:
        using std::runtime_error::runtime_error;
    };

    void require(const bool condition, const std::string_view message)
    {
        if (!condition)
        {
            throw TestFailure(std::string(message));
        }
    }

    // Single-segment channel covering [0, length] with stable id one.
    [[nodiscard]] quantum::coaster::ChannelProfile singleSegmentChannel(
        const double length,
        const double valueBegin,
        const double valueEnd,
        const quantum::math::TransitionType type)
    {
        using quantum::coaster::ChannelProfile;
        using quantum::coaster::ProfileSegment;
        using quantum::math::ScalarTransition;

        ChannelProfile profile;
        profile.segments.push_back(ProfileSegment{
            profile.nextSegmentId,
            ScalarTransition{0.0, length, valueBegin, valueEnd, type}
        });
        ++profile.nextSegmentId;
        return profile;
    }

    // Builds the same curved rate profiles used by AuthoredTrackTests so the
    // golden documents exercise nontrivial curvature and a chained joint.
    [[nodiscard]] AuthoredTrack createGoldenCurvedDocument()
    {
        using quantum::math::TransitionType;

        AuthoredTrack track;

        track.appendSection();
        setSectionLength(track.section(0), 90.0);
        {
            AuthoredTrackSection& section = track.section(0);
            section.rateProfileRegion().rateProfiles.roll =
                singleSegmentChannel(90.0, 0.024, 0.024, TransitionType::Smootherstep);
            section.rateProfileRegion().rateProfiles.pitch =
                singleSegmentChannel(90.0, 0.018, -0.010, TransitionType::CosineEaseInOut);
            section.rateProfileRegion().rateProfiles.yaw =
                singleSegmentChannel(90.0, 0.004, 0.022, TransitionType::Smoothstep);
        }

        track.appendSection();
        setSectionLength(track.section(1), 45.0);
        {
            AuthoredTrackSection& section = track.section(1);
            section.rateProfileRegion().rateProfiles.roll =
                singleSegmentChannel(45.0, 0.0, 0.0, TransitionType::Linear);
            section.rateProfileRegion().rateProfiles.pitch =
                singleSegmentChannel(45.0, 0.006, 0.006, TransitionType::CosineEaseInOut);
            section.rateProfileRegion().rateProfiles.yaw =
                singleSegmentChannel(45.0, 0.0, 0.0, TransitionType::Smoothstep);
        }

        return track;
    }

